import json
lines = [json.loads(l) for l in open('metrics.jsonl') if l.strip()]

def f(v, fmt='{:.4f}'):
    if isinstance(v, (int, float)):
        return fmt.format(v)
    return str(v)

print(f'{\"step\":>4} {\"score\":>8} {\"val_acc\":>8} {\"reward\":>8} {\"clip\":>8} {\"kl\":>8} {\"pg_clip\":>8} {\"gradnorm\":>9} {\"entropy\":>8} {\"resplen\":>8} {\"ppl\":>7} {\"loss\":>7}')
for l in lines:
    step = l['step']
    d = l['data']
    print(f'{step:>4} {f(d.get(\"critic/score/mean\")):>8} {f(d.get(\"val-core/openai/gsm8k/acc/mean@1\")):>8} {f(d.get(\"critic/rewards/mean\")):>8} {f(d.get(\"response_length/clip_ratio\")):>8} {f(d.get(\"actor/kl_loss\")):>8} {f(d.get(\"actor/pg_clipfrac\")):>8} {f(d.get(\"actor/grad_norm\")):>9} {f(d.get(\"actor/entropy\")):>8} {f(d.get(\"response_length/mean\")):>8} {f(d.get(\"rollout_corr/training_ppl\")):>7} {f(d.get(\"actor/loss\")):>7}')
"

